<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)$u['id'];$q=db()->prepare('SELECT * FROM student_profiles WHERE user_id=?');$q->execute([$id]);$p=$q->fetch();$skills=db()->query('SELECT * FROM skills WHERE active=1 ORDER BY name')->fetchAll();$subjects=db()->query('SELECT * FROM subjects WHERE active=1 ORDER BY name')->fetchAll();$us=db()->prepare('SELECT skill_id FROM user_skills WHERE user_id=?');$us->execute([$id]);$selectedSkills=array_column($us->fetchAll(),'skill_id');$us=db()->prepare('SELECT subject_id,intent FROM user_subjects WHERE user_id=?');$us->execute([$id]);$selectedSubjects=[];foreach($us as $x)$selectedSubjects[$x['intent']][]=$x['subject_id'];page_start('Edit profile'); ?><div class="card"><div class="card-body p-4"><form method="post" action="../actions/profile.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="name" value="<?= e($u['name']) ?>" required></div><div class="col-md-6"><label class="form-label">College / University</label><input class="form-control" name="college" value="<?= e($p['college']) ?>" required></div><div class="col-md-6"><label class="form-label">Course</label><input class="form-control" name="course" value="<?= e($p['course']) ?>" required></div><div class="col-md-2"><label class="form-label">Semester</label><input class="form-control" type="number" min="1" max="12" name="semester" value="<?= e($p['semester']) ?>"></div><div class="col-md-4"><label class="form-label">Profile photo (JPG, PNG, WEBP · max 2MB)</label><input class="form-control" type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><label class="form-label">About</label><textarea class="form-control" name="about" rows="3"><?= e($p['about']) ?></textarea></div><div class="col-12"><label class="form-label">Learning goals</label><textarea class="form-control" name="learning_goals" rows="2"><?= e($p['learning_goals']) ?></textarea></div><div class="col-md-4"><label class="form-label">Study mode</label><select class="form-select" name="study_mode"><option value="">Choose</option><?php foreach(['Online','Offline','Both'] as $x): ?><option <?= $p['study_mode']===$x?'selected':'' ?>><?= $x ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Available days</label><div><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d): ?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="days[]" value="<?= $d ?>" <?= in_array($d,explode(',',$p['availability_days']??''))?'checked':'' ?>><span class="form-check-label"><?= $d ?></span></label><?php endforeach ?></div></div><div class="col-md-2"><label class="form-label">From</label><input class="form-control" type="time" name="start_time" value="<?= e($p['start_time']) ?>"></div><div class="col-md-2"><label class="form-label">To</label><input class="form-control" type="time" name="end_time" value="<?= e($p['end_time']) ?>"></div><div class="col-12"><label class="form-label">Languages (comma separated)</label><input class="form-control" name="languages" value="<?= e($p['languages']) ?>"></div><div class="col-md-6"><h2 class="h6">Skills</h2><?php foreach($skills as $s): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="skills[]" value="<?= $s['id'] ?>" <?= in_array($s['id'],$selectedSkills)?'checked':'' ?>><span class="form-check-label"><?= e($s['name']) ?></span></label><?php endforeach ?></div><?php foreach(['help'=>'Subjects I can help with','want'=>'Subjects I want to learn'] as $intent=>$title): ?><div class="col-md-3"><h2 class="h6"><?= e($title) ?></h2><?php foreach($subjects as $s): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="subjects[<?= $intent ?>][]" value="<?= $s['id'] ?>" <?= in_array($s['id'],$selectedSubjects[$intent]??[])?'checked':'' ?>><span class="form-check-label"><?= e($s['name']) ?></span></label><?php endforeach ?></div><?php endforeach ?><div class="col-12"><button class="btn btn-primary">Save profile</button> <a class="btn btn-link" href="profile.php">Cancel</a></div></div></form></div></div><?php page_end(); ?>
